"""Actual CoreDNS Kubernetes plugin, isolated API credentials and loopback DNS only."""
import pathlib,re,subprocess,time
from native import free_port

class PrivateDNS:
    def __init__(self,cluster,ttl=2):
        assert type(ttl) is int and 0<=ttl<=30
        self.cluster=cluster;self.ttl=ttl;self.port=free_port();self.process=None
    def __enter__(self):
        root=self.cluster.root;self.corefile=root/('Corefile-'+str(self.port))
        self.corefile.write_text('.:'+str(self.port)+' {\n bind 127.0.0.1\n errors\n kubernetes cluster.local {\n  endpoint '+self.cluster.url+'\n  tls '+str(root/'admin.crt')+' '+str(root/'admin.key')+' '+str(root/'ca.crt')+'\n  ttl '+str(self.ttl)+'\n }\n}\n')
        self.process=self.cluster.spawn('coredns-'+str(self.port),['coredns','-conf',str(self.corefile)])
        try:
            self.wait('kubernetes.default.svc.cluster.local.',lambda reply:reply['status']=='NOERROR' and any(row['type']=='A' for row in reply['records']),12)
            print('NATIVE_COREDNS_KUBERNETES_API_WATCH_READY:1.12.0',flush=True)
            return self
        except BaseException:self.__exit__(None,None,None);raise
    def query(self,name,kind='A'):
        if not isinstance(name,str) or not name.endswith('.') or not re.fullmatch(r'[a-z0-9.-]+',name) or kind not in ('A','AAAA','CNAME'):raise ValueError('explicit DNS question required')
        process=subprocess.run(['dig','@127.0.0.1','-p',str(self.port),name,kind,'+time=1','+tries=1','+norecurse','+noall','+answer','+comments','+noedns'],capture_output=True,text=True,timeout=3)
        match=re.search(r'status: ([A-Z]+),',process.stdout)
        if process.returncode or not match:raise RuntimeError('owned DNS query failed: '+process.stdout+process.stderr)
        records=[]
        for line in process.stdout.splitlines():
            if not line or line.startswith(';'):continue
            fields=line.split();assert len(fields)==5 and fields[2]=='IN',line
            records.append(dict(name=fields[0].lower(),ttl=int(fields[1]),type=fields[3],data=fields[4]))
        return dict(status=match[1],records=records)
    def wait(self,name,predicate,timeout=8):
        deadline=time.monotonic()+timeout;last=None
        while time.monotonic()<deadline:
            if self.process.poll() is not None:raise RuntimeError((self.cluster.root/('coredns-'+str(self.port)+'.log')).read_text()[-6000:])
            try:
                last=self.query(name)
                if predicate(last):return last
            except RuntimeError as error:last=str(error)
            time.sleep(.1)
        raise RuntimeError('actual CoreDNS did not converge: '+str(last))
    def __exit__(self,*args):
        if self.process and self.process.poll() is None:
            self.process.terminate()
            try:self.process.wait(timeout=3)
            except subprocess.TimeoutExpired:self.process.kill();self.process.wait(timeout=3)

